/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 17/07/2021
/// The <c>METSAPPredictorHelper</c> class is a helper class to settle transactions according to customer account statment.
/// </summary>
public class METSAPPredictorHelper
{
    METSAPPredictorHelperContract   predictorHelperContract;

}

Method.Source:
/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 17/07/2021
/// Constructor
/// </summary>
/// <returns>Class object</returns>
public static METSAPPredictorHelper constructor()
{
    return new METSAPPredictorHelper();
}

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Weekly functionality
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTrans">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void autoSettelment(CustTransOpen _custTransOpen, CustTrans _custTrans, CustTable _custTable)
    {
        CustTransOpen               custTransOpenSettlement;
        boolean                     flag;

        flag = false;
        
        // Start Step 1 - Allocate to an individual open document by amount
        custTransOpenSettlement = this.getCustTransOpen(_custTransOpen, _custTrans, _custTable);

        if (custTransOpenSettlement && flag == false)
        {
            this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
            flag = true;
        }
        // End Step 1
        
        // Start step 2 - Sum of all open items (total for account) – using grouping logic
        if (_custTransOpen.AmountCur == -(this.getTotalCustOpenTransAmount(_custTable.AccountNum)) && flag == false)
        {
            this.settleTransSumAllOpenItems(_custTransOpen, _custTable);
            flag = true;
        }
        // End step 2
               
        // Start step 3 - Sum of each statement period starting with the current period then work backwards.
        if (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep3(), predictorHelperContract.getEndDateStep3());
                        
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
        }
        // End step 3
        
        // Start step 4 - Sum of each statement period starting with current period then work forward.
        if  (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep4(), predictorHelperContract.getEndDateStep4());
                        
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
        }
        // End step 4

        // Start step 5 - Sum of two consecutive periods starting with the most recent periods working backward.
        if  (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep5());
                        
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
            else
            {
                //check total of invoices between 2 periods of all inoivces
                if(_custTransOpen.AmountCur == -(this.getTotalCustOpenTransAmountByDate(_custTable.AccountNum, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep3())))
                {
                    this.settleMultipleTransactionDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep5(), predictorHelperContract.getEndDateStep3());
                    flag = true;
                }
            }
        }
        // End step 5

        // Start step 6 - Sum of two consecutive periods starting with the most recent periods working forwards.
        if  (flag == false)
        {
            custTransOpenSettlement = this.getCustTransOpenByDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep6(), predictorHelperContract.getEndDateStep6());
            
            if (custTransOpenSettlement)
            {
                this.settleTransaction(_custTransOpen, _custTable, custTransOpenSettlement);
                flag = true;
            }
            else
            {
                //check total of invoices between 2 periods of all inoivces
                if(_custTransOpen.AmountCur == -(this.getTotalCustOpenTransAmountByDate(_custTable.AccountNum, predictorHelperContract.getStartDateStep4(), predictorHelperContract.getEndDateStep6())))
                {
                    this.settleMultipleTransactionDate(_custTransOpen, _custTable, predictorHelperContract.getStartDateStep4(), predictorHelperContract.getEndDateStep6());
                    flag = true;
                }
            }
        }
        // End step 6
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Set dates according to account statment.
    /// </summary>
    /// <param name = "_CustAccountStatement">customer account statment</param>
    public void setDates(CustAccountStatement _CustAccountStatement)
    {
        predictorHelperContract = METSAPPredictorHelperContract::constructor();

        switch (_CustAccountStatement)
        {
            case CustAccountStatement::AMEXWeekly:
                this.weeklySetDates();
                break;

            case CustAccountStatement::AMEXFortnightly:
                this.fortnightlySetDates();
                break;

            case CustAccountStatement::AMEXMonthly:
                this.monthlySetDates();
                break;

            case CustAccountStatement::AMEXPeriod:
                this.periodSetDates();
                break;

            default:
                info("@MET:SAPPredictorDefault");
                break;
        }
    }

 /// <summary>
 /// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
 /// Set dates according to account statment for weekly.
 /// </summary>
public void weeklySetDates()
{
     predictorHelperContract.setStartDateStep3(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-2);
     predictorHelperContract.setEndDateStep3(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-2);
     predictorHelperContract.setStartDateStep4(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+5);
     predictorHelperContract.setEndDateStep4(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+5);        
     predictorHelperContract.setStartDateStep5(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-9);
     predictorHelperContract.setEndDateStep5(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-9);
     predictorHelperContract.setStartDateStep6(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+12);
     predictorHelperContract.setEndDateStep6(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+12);
}

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
/// Set dates according to account statment for fortnightly
/// </summary>
 public void fortnightlySetDates()
 {
     predictorHelperContract.setStartDateStep3(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-9);
     predictorHelperContract.setEndDateStep3(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-2);
     predictorHelperContract.setStartDateStep4(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+5);
     predictorHelperContract.setEndDateStep4(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+12);
     predictorHelperContract.setStartDateStep5(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-23);
     predictorHelperContract.setEndDateStep5(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-16);
     predictorHelperContract.setStartDateStep6(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+19);
     predictorHelperContract.setEndDateStep6(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+26);
 }

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
/// Set dates according to account statment for monthly.
/// </summary>
public void monthlySetDates()
{
    predictorHelperContract.setStartDateStep3(dateStartMth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    predictorHelperContract.setEndDateStep3(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),1))));
    predictorHelperContract.setStartDateStep4(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),1))));
    predictorHelperContract.setEndDateStep4(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),2))));
    predictorHelperContract.setStartDateStep5(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),-1))));
    predictorHelperContract.setEndDateStep5(dateStartMth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    predictorHelperContract.setStartDateStep6(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),2))));
    predictorHelperContract.setEndDateStep6(dateStartMth(DatetimeUtil::Date(DateTimeUtil::addMonths(DateTimeUtil::newDateTime(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()),0),3))));
}

/// <summary>
/// MPJ_3972_SAPPredictor - kscerri - 16/07/2021
/// Set dates according to account statment for 28 days.
/// </summary>
public void periodSetDates()
{
    predictorHelperContract.setStartDateStep3(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-30);
    predictorHelperContract.setEndDateStep3(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-2);
    predictorHelperContract.setStartDateStep4(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+5);
    predictorHelperContract.setEndDateStep4(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+26);
    predictorHelperContract.setStartDateStep5(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-51);
    predictorHelperContract.setEndDateStep5(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))-30);
    predictorHelperContract.setStartDateStep6(DateTimeUtil::getStartOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+33);
    predictorHelperContract.setEndDateStep6(DateTimeUtil::getEndOfWeekDate(METConstants::preferredlocale, DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()))+54);
}

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 1 fnd record which matches same payment price
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTrans">CustTrans buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    /// <returns>Returns custtransopen record buffer</returns>
    public CustTransOpen getCustTransOpen(CustTransOpen _custTransOpen, CustTrans _custTrans, CustTable _custTable)
    {
        CustTransOpen   custTransOpen;
        CustTrans       custTrans;
        CustDispute     custDispute;
        SpecTrans       specTrans;

        select firstonly custTransOpen
            where custTransOpen.AccountNum == _custTable.accountNum
               && custTransOpen.AmountCur == -(_custTransOpen.AmountCur)
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                   && custTrans.AccountNum == custTransOpen.AccountNum
                   && custTrans.TransType != LedgerTransType::Payment
                   && _custTrans.PaymReference == custTrans.Invoice
            exists join custDispute
                where custDispute.CustTrans == custTransOpen.RefRecId
                   && custDispute.Status    != CustVendDisputeStatus::Disputed
                   && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId;

        return custTransOpen;
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 1 settelment
    /// </summary>
    /// <param name = "_custTransOpen">Original Selection</param>
    /// <param name = "_custTable">Customer record</param>
    /// <param name = "_invoiceToSettle">debit/credit line to settle</param>
    public void settleTransaction(CustTransOpen _custTransOpen, CustTable _custTable, CustTransOpen _invoiceToSettle)
    {
        CustVendOpenTransManager    settleManager;

        settleManager = custVendOpenTransManager::construct(_custTable);

        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
        SettleManager.updateTransMarked(_invoiceToSettle, true);
        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 2 settelment & adding all transctions according to customer if these add up to the total payment amount
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void settleTransSumAllOpenItems(CustTransOpen _custTransOpen, CustTable _custTable)
    {
        CustVendOpenTransManager    settleManager;
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        CustDispute                 custDispute;
        SpecTrans                   specTrans;

        settleManager = custVendOpenTransManager::construct(_custTable);
        
        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
                
        // Mark all open trans to match customer payment
        while select custTransOpen
            where custTransOpen.AccountNum == _custTable.AccountNum
        exists join custTrans
            where custTrans.RecId == custTransOpen.RefRecId
               && custTrans.AccountNum == custTransOpen.AccountNum
               && custTrans.TransType != LedgerTransType::Payment
        exists join custDispute
            where custDispute.CustTrans == custTransOpen.RefRecId
                && custDispute.Status    != CustVendDisputeStatus::Disputed
                && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
        notexists join specTrans
            where specTrans.RefRecId    == custTransOpen.RecId
                && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            SettleManager.updateTransMarked(custTransOpen, true);
        }

        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 3, 4, 5 and 6 transaction return
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    /// <param name = "_startDate">startDate</param>
    /// <param name = "_endDate">EndDate</param>
    /// <returns>CustTrans buffer</returns>
    public custTransOpen getCustTransOpenByDate(CustTransOpen _custTransOpen, CustTable _custTable, date _startDate, date _endDate)
    {
        CustTransOpen   custTransOpen;
        CustTrans       custTrans;
        CustDispute     custDispute;
        SpecTrans       specTrans;

        select firstonly custTransOpen
            order by custTransOpen.DueDate desc
                where custTransOpen.DueDate >= _startDate
                   && custTransOpen.DueDate <= _endDate
                   && custTransOpen.AmountCur == -(_custTransOpen.AmountCur)
                   && custTransOpen.AccountNum == _custTable.accountNum
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                    && custTrans.AccountNum == custTransOpen.AccountNum
                    && custTrans.TransType != LedgerTransType::Payment
            exists join custDispute
                where custDispute.CustTrans == custTransOpen.RefRecId
                   && custDispute.Status    != CustVendDisputeStatus::Disputed
                   && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId;

        return custTransOpen;
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 5 and 6 - Settle multiple transactions backdated from the currenct system date
    /// </summary>
    /// <param name = "_custTransOpen">CusttransOpen buffer</param>
    /// <param name = "_custTable">custtable buffer</param>
    /// <param name = "_startDate">Previous Saturday date</param>
    /// <param name = "_endDate">This Friday date</param>
    public void settleMultipleTransactionDate(CustTransOpen _custTransOpen, CustTable _custTable, date _startDate, date _endDate)
    {
        CustVendOpenTransManager    settleManager;
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        CustDispute                 custDispute;
        SpecTrans                   specTrans;

        settleManager = custVendOpenTransManager::construct(_custTable);
        
        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
                
        // Mark all open trans to match customer payment
        while select custTransOpen
            where custTransOpen.AccountNum == _custTable.AccountNum
               && custTransOpen.DueDate >= _startDate
               && custTransOpen.DueDate <= _endDate
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                   && custTrans.AccountNum == custTransOpen.AccountNum
                   && custTrans.TransType != LedgerTransType::Payment
            exists join custDispute
                where custDispute.CustTrans == custTransOpen.RefRecId
                   && custDispute.Status    != CustVendDisputeStatus::Disputed
                   && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            SettleManager.updateTransMarked(custTransOpen, true);
        }

        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Step 7 settle using past transactions
    /// </summary>
    /// <param name = "_custTransOpen">CustTransOpen buffer</param>
    /// <param name = "_custTable">CustTable buffer</param>
    public void settleFromPastOpenTrans(CustTransOpen _custTransOpen, CustTable _custTable)
    {
        CustVendOpenTransManager    settleManager;
        CustTransOpen               custTransOpen;
        CustTrans                   custTrans;
        AmountCurDebCred            settleAmount;
        CustDispute                 custDispute;
        SpecTrans                   specTrans;

        settleManager = custVendOpenTransManager::construct(_custTable);
        
        // Customer payment marked
        SettleManager.updateTransMarked(_custTransOpen, true);
                
        // Mark all open trans to match customer payment until price match to settle payment
        while select custTransOpen
            order by custTransOpen.DueDate asc
                where custTransOpen.AccountNum == _custTable.AccountNum
            join SettleAmountCur from custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                   && custTrans.AccountNum == custTransOpen.AccountNum
                   && custTrans.TransType != LedgerTransType::Payment
            exists join custDispute
                where custDispute.CustTrans == custTransOpen.RefRecId
                   && custDispute.Status    != CustVendDisputeStatus::Disputed
                   && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId
        {
            if (settleAmount <= -(_custTransOpen.AmountCur))
            {
                SettleManager.updateTransMarked(custTransOpen, true);
                settleAmount = settleAmount + custTransOpen.AmountCur;
            }
            else
            {
                break;
            }
        }

        SettleManager.settleMarkedTrans();
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Returns total amount of open cust trans depending on customer acc
    /// </summary>
    /// <param name = "_accountNum">account num</param>
    /// <returns>total amount cur</returns>
    public AmountCurDebCred getTotalCustOpenTransAmount(CustAccount _accountNum)
    {
        CustTransOpen   custTransOpen;
        CustTrans       custTrans;
        CustDispute     custDispute;
        SpecTrans       specTrans;

        select sum(AmountCur) from custTransOpen
            where custTransOpen.AccountNum == _accountNum
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                    && custTrans.AccountNum == custTransOpen.AccountNum
                    && custTrans.TransType != LedgerTransType::Payment
            exists join custDispute
                where custDispute.CustTrans == custTransOpen.RefRecId
                   && custDispute.Status    != CustVendDisputeStatus::Disputed
                   && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId;

        return custTransOpen.AmountCur;
    }

    /// <summary>
    /// MPJ_3972_SAPPredictor - kscerri - 12/07/2021
    /// Returns total amount of open cust trans depending on customer acc
    /// </summary>
    /// <param name = "_accountNum">customer account number </param>
    /// <param name = "_startDate">start date</param>
    /// <param name = "_endDate">end date</param>
    /// <returns>total amount for selected dates</returns>
    public AmountCurDebCred getTotalCustOpenTransAmountByDate(CustAccount _accountNum, date _startDate, date _endDate)
    {
        CustTransOpen   custTransOpen;
        CustTrans       custTrans;
        CustDispute     custDispute;
        SpecTrans       specTrans;

        select sum(AmountCur) from custTransOpen
            where custTransOpen.AccountNum  == _accountNum
               && custTransOpen.DueDate     >= _startDate
               && custTransOpen.DueDate     <= _endDate
            exists join custTrans
                where custTrans.RecId == custTransOpen.RefRecId
                   && custTrans.AccountNum == custTransOpen.AccountNum
                   && custTrans.TransType != LedgerTransType::Payment
            exists join custDispute
                where custDispute.CustTrans == custTransOpen.RefRecId
                   && custDispute.Status    != CustVendDisputeStatus::Disputed
                   && custDispute.Status    != CustVendDisputeStatus::PromiseToPay
            notexists join specTrans
                where specTrans.RefRecId    == custTransOpen.RecId
                   && specTrans.RefTableId  == tableName2Id(tableStr(CustTransOpen))
                   && specTrans.RefCompany  == custTransOpen.DataAreaId;

        return custTransOpen.AmountCur;
    }
